-- Run OWNER-SETUP-v52.sql first and authorise your own Supabase Auth UUID.
-- v53 adds owner-only management with an audit trail and public announcements.
create table if not exists public.local_announcements(id uuid primary key default gen_random_uuid(),title text not null check(length(title) between 1 and 120),body text not null check(length(body) between 1 and 5000),image_url text, published boolean not null default false,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists public.local_member_status(user_id uuid primary key references auth.users(id) on delete cascade,status text not null default 'active' check(status in ('active','suspended','banned')),reason text,updated_at timestamptz not null default now(),updated_by uuid references auth.users(id));
create table if not exists public.local_owner_audit_log(id bigint generated always as identity primary key,actor uuid references auth.users(id),action text not null,details text not null,created_at timestamptz not null default now());
alter table public.local_announcements enable row level security;
alter table public.local_member_status enable row level security;
alter table public.local_owner_audit_log enable row level security;
revoke all on public.local_announcements,public.local_member_status,public.local_owner_audit_log from anon,authenticated;
grant select on public.local_announcements to authenticated;
create or replace function public.local_my_account_status() returns text language sql stable security definer set search_path='' as $$select coalesce((select status from public.local_member_status where user_id=auth.uid()),'active')$$;
revoke all on function public.local_my_account_status() from public,anon;
grant execute on function public.local_my_account_status() to authenticated;
drop policy if exists "Members can read published news" on public.local_announcements;
create policy "Members can read published news" on public.local_announcements for select to authenticated using (published=true and public.local_my_account_status()='active');

create or replace function public.local_owner_members(p_search text default '') returns jsonb language plpgsql security definer set search_path='' as $$declare result jsonb;begin if not public.local_is_owner() then raise exception 'Owner only' using errcode='42501';end if;select coalesce(jsonb_agg(to_jsonb(x)),'[]'::jsonb) into result from (select u.id,u.email,coalesce(s.status,'active') status from auth.users u left join public.local_member_status s on s.user_id=u.id where (p_search='' or u.email ilike '%'||p_search||'%' or u.id::text ilike '%'||p_search||'%') order by u.created_at desc limit 75) x;return result;end$$;
create or replace function public.local_owner_set_member_status(p_user_id uuid,p_status text,p_reason text) returns void language plpgsql security definer set search_path='' as $$begin if not public.local_is_owner() then raise exception 'Owner only' using errcode='42501';end if;if p_status not in ('active','suspended','banned') or length(trim(p_reason))<3 then raise exception 'Valid status and reason required';end if;if p_user_id=auth.uid() or exists(select 1 from public.local_platform_owners where user_id=p_user_id) then raise exception 'Cannot restrict platform owner';end if;if not exists(select 1 from auth.users where id=p_user_id) then raise exception 'Member not found';end if;insert into public.local_member_status(user_id,status,reason,updated_at,updated_by) values(p_user_id,p_status,p_reason,now(),auth.uid()) on conflict(user_id) do update set status=excluded.status,reason=excluded.reason,updated_at=now(),updated_by=auth.uid();insert into public.local_owner_audit_log(actor,action,details) values(auth.uid(),'member_status',p_user_id::text||' -> '||p_status||': '||p_reason);end$$;
create or replace function public.local_owner_save_announcement(p_title text,p_body text,p_image_url text default null,p_publish boolean default false) returns uuid language plpgsql security definer set search_path='' as $$declare new_id uuid;begin if not public.local_is_owner() then raise exception 'Owner only' using errcode='42501';end if;if length(trim(p_title)) not between 1 and 120 or length(trim(p_body)) not between 1 and 5000 then raise exception 'Title or body length invalid';end if;if p_image_url is not null and (length(p_image_url)>1500 or p_image_url !~ '^https://') then raise exception 'Image URL must use HTTPS';end if;insert into public.local_announcements(title,body,image_url,published) values(trim(p_title),trim(p_body),p_image_url,p_publish) returning id into new_id;insert into public.local_owner_audit_log(actor,action,details) values(auth.uid(),'announcement_create',new_id::text||case when p_publish then ' published' else ' draft' end);return new_id;end$$;
create or replace function public.local_owner_announcements() returns jsonb language sql security definer set search_path='' as $$select case when public.local_is_owner() then coalesce((select jsonb_agg(to_jsonb(x)) from (select id,title,body,published,created_at from public.local_announcements order by created_at desc limit 100)x),'[]'::jsonb) else '[]'::jsonb end$$;
create or replace function public.local_owner_announcement_action(p_id uuid,p_action text) returns void language plpgsql security definer set search_path='' as $$begin if not public.local_is_owner() then raise exception 'Owner only' using errcode='42501';end if;if p_action='delete' then delete from public.local_announcements where id=p_id;elsif p_action in ('publish','unpublish') then update public.local_announcements set published=(p_action='publish'),updated_at=now() where id=p_id;else raise exception 'Invalid action';end if;insert into public.local_owner_audit_log(actor,action,details) values(auth.uid(),'announcement_'||p_action,p_id::text);end$$;
create or replace function public.local_owner_audit() returns jsonb language sql security definer set search_path='' as $$select case when public.local_is_owner() then coalesce((select jsonb_agg(to_jsonb(x)) from (select action,details,created_at from public.local_owner_audit_log order by created_at desc limit 30)x),'[]'::jsonb) else '[]'::jsonb end$$;
revoke all on function public.local_owner_members(text),public.local_owner_set_member_status(uuid,text,text),public.local_owner_save_announcement(text,text,text,boolean),public.local_owner_announcements(),public.local_owner_announcement_action(uuid,text),public.local_owner_audit() from public,anon;
grant execute on function public.local_owner_members(text),public.local_owner_set_member_status(uuid,text,text),public.local_owner_save_announcement(text,text,text,boolean),public.local_owner_announcements(),public.local_owner_announcement_action(uuid,text),public.local_owner_audit() to authenticated;
-- IMPORTANT: App-level restrictions do not revoke Supabase Auth tokens or
-- protect legacy tables. Add account-status checks to EVERY legacy RLS policy
-- and RPC before treating a ban as platform-wide enforcement.
